#!/usr/bin/env python3
"""Independent source-space mathematics, no producer/SymPy/test execution.

Uses factorial Wigner-d integrals, exact radical matrices and Fraction block
algebra. Only writes arithmetic-evidence.json in this owned audit directory.
"""
import ast
from datetime import datetime, timezone
from fractions import Fraction as Q
import hashlib
import json
from math import factorial, gcd
from pathlib import Path


HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[4]
RUN = ROOT / 'outputs/learning-daily/20261007-DAY8-angular-momentum-selection-rules-multipolarity-run-01'
RECEIPT = RUN / 'truncation-observable-bound.json'


def scalar(value):
    return {} if not value else {(1, 0): Q(value)}


def radical(n):
    factor, prime = 1, 2
    while prime * prime <= n:
        while n % (prime * prime) == 0:
            n //= prime * prime
            factor *= prime
        prime += 1
    return {(n, 0): Q(factor)}


def add(a, b):
    out = dict(a)
    for key, value in b.items():
        out[key] = out.get(key, Q(0)) + value
    return {key: value for key, value in out.items() if value}


def scale(a, value):
    return {key: coefficient * value for key, coefficient in a.items() if value}


def mul(a, b):
    out = {}
    for (na, ia), va in a.items():
        for (nb, ib), vb in b.items():
            common = gcd(na, nb)
            key = ((na // common) * (nb // common), (ia + ib) % 2)
            value = va * vb * common * (-1 if ia + ib == 2 else 1)
            out = add(out, {key: value})
    return out


def conj(a):
    return {(n, i): value * (-1 if i else 1) for (n, i), value in a.items()}


def parse_node(node):
    if isinstance(node, ast.Constant) and type(node.value) is int:
        return scalar(node.value)
    if isinstance(node, ast.Name) and node.id == 'I':
        return {(1, 1): Q(1)}
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub)):
        return scale(parse_node(node.operand), -1 if isinstance(node.op, ast.USub) else 1)
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id == 'sqrt':
        if len(node.args) != 1 or node.keywords or not isinstance(node.args[0], ast.Constant):
            raise ValueError('Unexpected sqrt')
        return radical(node.args[0].value)
    if not isinstance(node, ast.BinOp):
        raise ValueError('Outside exact scalar grammar')
    a, b = parse_node(node.left), parse_node(node.right)
    if isinstance(node.op, ast.Add):
        return add(a, b)
    if isinstance(node.op, ast.Sub):
        return add(a, scale(b, -1))
    if isinstance(node.op, ast.Mult):
        return mul(a, b)
    if isinstance(node.op, ast.Div) and set(b) == {(1, 0)}:
        return scale(a, 1 / b[(1, 0)])
    raise ValueError('Unexpected scalar operation')


def parse(value):
    return parse_node(ast.parse(value, mode='eval').body)


def mm(a, b):
    return [[sum_scalar(mul(a[i][k], b[k][j]) for k in range(len(b)))
             for j in range(len(b[0]))] for i in range(len(a))]


def sum_scalar(values):
    out = {}
    for value in values:
        out = add(out, value)
    return out


def adjoint(a):
    return [[conj(a[i][j]) for i in range(len(a))] for j in range(len(a[0]))]


def eye(n):
    return [[scalar(int(i == j)) for j in range(n)] for i in range(n)]


def zeros(n, m):
    return [[{} for _ in range(m)] for _ in range(n)]


def ms(a, value):
    return [[scale(entry, value) for entry in row] for row in a]


def ma(a, b):
    return [[add(a[i][j], b[i][j]) for j in range(len(a[0]))] for i in range(len(a))]


def trace(a):
    return sum_scalar(a[i][i] for i in range(len(a)))


def tensor(a, b):
    return [[mul(a[i // len(b)][j // len(b[0])], b[i % len(b)][j % len(b[0])])
             for j in range(len(a[0]) * len(b[0]))] for i in range(len(a) * len(b))]


def ff(value):
    value = Q(value)
    if value.denominator != 1 or value < 0:
        raise ValueError('Invalid factorial argument')
    return factorial(value.numerator)


def cg(j1, j2, J, m1, m2, M):
    if m1 + m2 != M or abs(m1) > j1 or abs(m2) > j2 or abs(M) > J:
        return {}
    triangle = Q(ff(j1 + j2 - J) * ff(j1 - j2 + J) * ff(-j1 + j2 + J), ff(j1 + j2 + J + 1))
    norm_square = Q(2 * J + 1) * triangle
    for j, m in ((j1, m1), (j2, m2), (J, -M)):
        norm_square *= ff(j + m) * ff(j - m)
    lower = int(max(0, j2 - J - m1, j1 + m2 - J))
    upper = int(min(j1 + j2 - J, j1 - m1, j2 + m2))
    summation = Q(0)
    for index in range(lower, upper + 1):
        denominator = ff(index) * ff(j1 + j2 - J - index) * ff(j1 - m1 - index)
        denominator *= ff(j2 + m2 - index) * ff(J - j2 + m1 + index) * ff(J - j1 - m2 + index)
        summation += Q((-1) ** index, denominator)
    return scale(radical(norm_square.numerator * norm_square.denominator), summation / norm_square.denominator)


def d_terms(L, m, q):
    # Independent factorial formula; a theta sign convention multiplies each
    # d_Lmq by the same (-1)^(m-q), leaving all Gram products unchanged.
    norm = ff(L + q) * ff(L - q) * ff(L + m) * ff(L - m)
    out = []
    for index in range(max(0, q - m), min(L + q, L - m) + 1):
        ps, pc = m - q + 2 * index, 2 * L + q - m - 2 * index
        denominator = ff(L + q - index) * ff(index) * ff(m - q + index) * ff(L - m - index)
        out.append((ps, pc, Q((-1) ** (m - q + index), denominator)))
    return norm, out


def d_inner(L, LP, m, q):
    na, a = d_terms(L, m, q)
    nb, b = d_terms(LP, m, q)
    total = Q(0)
    for sa, ca, va in a:
        for sb, cb, vb in b:
            sh, ch = (sa + sb) // 2, (ca + cb) // 2
            if (sa + sb) % 2 or (ca + cb) % 2:
                raise ValueError('Unexpected odd product power')
            total += va * vb * Q(ff(sh) * ff(ch), ff(sh + ch + 1))
    return scale(radical(na * nb), total)


def main():
    before = RECEIPT.read_bytes()
    data = json.loads(before)
    tracked = {RECEIPT: before}
    inputs = []
    for item in data['inputs']:
        path = ROOT / item['path']
        content = path.read_bytes()
        tracked[path] = content
        digest = hashlib.sha256(content).hexdigest()
        inputs.append({**item, 'observed_sha256': digest, 'matches': digest == item['sha256']})
    control = data['source_isometry_construction']['explicit_control']
    angular = []
    for L in (1, 2):
        for LP in (1, 2):
            for m in range(-min(L, LP), min(L, LP) + 1):
                for q in (-1, 1):
                    result = d_inner(L, LP, m, q)
                    expected = scalar(Q(1, 2 * L + 1) if L == LP else 0)
                    key = f'L{L}_LP{LP}_m{m}_q{q}'
                    angular.append({'key': key, 'independent_factorial_integral_matches': result == expected,
                                    'matches_saved_exact_value': result == parse(control['full_sphere_d_integrals'][key])})
    VR = [[parse(value) for value in row] for row in control['V_R_E1']]
    VO = [[parse(value) for value in row] for row in control['V_O_M2']]
    initial = [Q(value) for value in control['initial_M_order']]
    final = Q(-1, 2), Q(1, 2)
    source_norm = []
    for L in (1, 2):
        for Mi in initial:
            value = sum_scalar(mul(cg(Q(1, 2), L, Q(3, 2), Mf, Mi - Mf, Mi),
                                  cg(Q(1, 2), L, Q(3, 2), Mf, Mi - Mf, Mi)) for Mf in final)
            source_norm.append({'L': L, 'Mi': str(Mi), 'norm_is_one': value == scalar(1)})
    rho = [[parse(value) for value in row] for row in control['complex_PSD_initial_density_control']]
    psi = [scalar(1), {(1, 1): Q(1)}, scalar(Q(1, 2)), {(1, 1): Q(-1, 3)}]
    pure = [[scale(mul(a, conj(b)), Q(36, 85)) for b in psi] for a in psi]
    rho_constructed = ma(ms(pure, Q(2, 3)), ms(eye(4), Q(1, 12)))
    e, t = Q(9, 25), Q(12, 25)
    K = [[scalar(-e), scalar(t)], [scalar(t), scalar(e)]]
    K_complex = [[scalar(-e), {(1, 1): t}], [{(1, 1): -t}, scalar(e)]]
    delta = tensor(K, rho)
    absolute_delta = ms(tensor(eye(2), rho), Q(3, 5))
    point_links = {L: mul(radical(2 * L + 1), cg(2, L, 2, 1, 1, 2)) for L in (1, 2, 3)}
    cancel = scale(radical(105), Q(-1, 15))
    p = e ** 2 * (1 - e) + e
    q = e ** 2
    conditional_D_squared = e / p
    code_path = ROOT / data['reproducibility']['script_path']
    code = code_path.read_bytes()
    tracked[code_path] = code
    facts = {
        'immutable_inputs_match': all(item['matches'] for item in inputs),
        'producer_sha_and_embedded_code_match': hashlib.sha256(code).hexdigest() == data['reproducibility']['script_sha256'] and code.decode() == data['reproducibility']['source_code'],
        'independent_angular_integrals_all_match': all(item['independent_factorial_integral_matches'] and item['matches_saved_exact_value'] for item in angular),
        'all_CG_coupled_source_norms_one': all(item['norm_is_one'] for item in source_norm),
        'saved_VR_gram_identity': mm(adjoint(VR), VR) == eye(4),
        'saved_VO_gram_identity': mm(adjoint(VO), VO) == eye(4),
        'saved_cross_gram_zero': mm(adjoint(VR), VO) == zeros(4, 4),
        'same_rank_EM_helicity_sum_zero': sum(Q(helicity, 2) for helicity in (-1, 1)) == 0,
        'complex_rho_matches_PSD_constructed_matrix': rho == rho_constructed,
        'rho_Hermitian_trace_one': rho == adjoint(rho) and trace(rho) == scalar(1),
        'real_and_complex_sector_K_square_eI': mm(K, K) == ms(eye(2), e) and mm(K_complex, K_complex) == ms(eye(2), e),
        'tensor_absolute_square_matches': mm(absolute_delta, absolute_delta) == mm(adjoint(delta), delta),
        'positive_absolute_trace_gives_sqrt_e': trace(absolute_delta) == scalar(Q(6, 5)),
        'cap_P2_integral_exact_three_over32': ((Q(1) ** 3 - Q(1)) - (Q(1, 2) ** 3 - Q(1, 2))) / 4 == Q(3, 32),
        'cap_retained_probability_is19_over64': Q(1, 4) + Q(1, 2) * Q(3, 32) == Q(19, 64),
        'point_node_M1_plus_E2_cancels': add(point_links[1], mul(cancel, point_links[2])) == {},
        'point_node_M3_intensity_is_three_over4': scale(mul(point_links[3], point_links[3]), Q(1, 2)) == scalar(Q(3, 4)),
        'rare_filter_success_and_conditional_distance_square': p == e * (1 + e - e ** 2) and q == e ** 2 and conditional_D_squared == 1 / (1 + e - e ** 2),
        'all_read_input_bytes_unchanged': all(path.read_bytes() == content for path, content in tracked.items()),
    }
    result = {
        'status': 'independent-radiation-arithmetic-supported' if all(facts.values()) else 'independent-radiation-arithmetic-needs-attention',
        'created_at_utc': datetime.now(timezone.utc).isoformat(), 'reviewed_receipt_sha256': hashlib.sha256(before).hexdigest(),
        'method': 'Independent factorial Wigner-d beta integrals; Racah CG coefficients; exact radical/complex Fraction matrix algebra; analytical channel/conditional proof in README. No producer or software tests.',
        'facts': facts, 'input_hashes': inputs, 'angular_integrals': angular, 'source_CG_norms': source_norm,
        'tensor_control': {'epsilon_exact': str(e), 'sector_coherence_exact': str(t), 'full_D_exact': '3/5', 'rho_PSD_spectrum': ['3/4', '1/12', '1/12', '1/12'],
                           'boundary': 'An exact rational control of the general symbolic proof, not a numerical experiment or all-parameter test.'},
        'rare_filter_control': {'epsilon_exact': str(e), 'full_success': str(p), 'retained_success': str(q), 'conditional_D_squared': str(conditional_D_squared),
                                'all_parameter_limit': 'p=e(1+e-e^2),q=e^2,Dconditional^2=1/(1+e-e^2)->1; proved by algebra in README.'},
        'analytic_proofs_not_replaced_by_arithmetic_control': ['all initial coherence operator Gram', 'arbitrary PSD rho trace distance', 'CPTP reduction/effect bound', 'postselection d/max(p,q)', 'different-initial-state triangle'],
        'producer_executed': False, 'software_tests_run': False,
    }
    (HERE / 'arithmetic-evidence.json').write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n')
    print(json.dumps({'status': result['status'], 'facts': facts, 'independent_integrals': len(angular), 'source_CG_norms': len(source_norm)}, ensure_ascii=False, indent=2))


if __name__ == '__main__':
    main()
